// 🌀 Loading Spinner Dots (Shader) ⚪️:

// Author: Mirza Beig
// https://x.com/TheMirzaBeig/status/1875145304447590666

// https://twitter.com/TheMirzaBeig
// https://www.youtube.com/@MirzaBeig

// Feel free to use this however you want.
// Modify, learn from it, copy-paste, etc...

void mainImage(out vec4 c, vec2 f)
{
    vec2 r = iResolution.xy, u = (2. * f - r) / r.y; float i, d;

    while (i < 10.)

        d += step(length(u - vec2(cos(.63 * i), sin(.63 * i)) * .7) -
        .1 * mod(iTime * -.8 - i++ * .1, 1.), 0.);

    c = vec4(d);
}
